const $=id=>document.getElementById(id),pct=v=>v===null?'Undefined':(100*v).toFixed(1)+'%',num=v=>v.toLocaleString(),per=v=>v===null?'Undefined':(1000*v).toFixed(1),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusLabel={pass:'Pass',fail:'Fail',insufficient:'More evidence needed'};
const pill=s=>`<span class="pill ${s}">${statusLabel[s]}</span>`;
const scenarioNames={wear:'Gradual wear',noise:'Noisy sensors and sudden faults',shift:'Changed conditions'};
const scenarioCopy={wear:'Wear builds gradually. Sensor readings provide relatively clear clues before a failure.',noise:'Measurements are noisier, and some failures occur suddenly without a useful advance signal.',shift:'Training and validation use cleaner conditions. Later, held-out machines face higher loads, noisier sensors, and sudden faults.'};
const stopNames={validation_target:'Validation target reached',validation_plateau:'Validation loss plateaued',epoch_budget:'50-epoch budget exhausted'};
let worker=null,result=null;
function updateDescription(){$('scenario-copy').textContent=scenarioCopy[$('scenario').value];}
function settings(){const seed=Number($('seed').value);if(!Number.isInteger(seed)||seed<1||seed>999999)throw Error('Use a whole-number simulation seed from 1 to 999999.');const policy={confidence:$('confidence').checked};for(const k of ['recall','precision','fpr']){if($(k).value==='')throw Error('Fill in all acceptance targets.');const n=Number($(k).value),max=k==='fpr'?1000:100;if(!Number.isFinite(n)||n<0||n>max)throw Error(`Enter a valid ${k} target.`);policy[k]=n/max;}return {scenario:$('scenario').value,seed,policy};}
function changed(){updateDescription();if(result){$('settings-note').textContent='Settings changed. Displayed results still use the previous policy. Run a new experiment to apply these settings.';$('settings-note').className='helper warning-text';}}
function lock(on){for(const e of $('settings').querySelectorAll('input,select'))e.disabled=on;$('run').disabled=on;$('cancel').hidden=!on;}
function stop(){if(worker)worker.terminate();worker=null;lock(false);$('progress').hidden=true;$('ready').hidden=!!result;$('results').hidden=!result;}
$('settings').onsubmit=e=>{e.preventDefault();try{const config=settings();$('error').textContent='';$('settings-note').textContent='';if(worker)worker.terminate();lock(true);$('ready').hidden=true;$('results').hidden=true;$('progress').hidden=false;$('progress-title').textContent='Generating 100 synthetic machines…';$('progress-bar').value=0;worker=new Worker('/factory-worker.js',{type:'module'});let progress=0;worker.onmessage=event=>{const m=event.data;if(m.type==='progress'){$('progress-bar').value=++progress;$('progress-title').textContent=m.phase==='training'?`Training on ${m.machines} machines…`:m.phase==='stability'?`Checking a different training seed (${m.seed})…`:m.phase==='repeat'?'Repeating the exact same training setup…':'Evaluating the frozen models on unseen machines…';}else if(m.type==='complete'){result=m.result;stop();$('results').hidden=false;render();}else{$('error').textContent=m.message;stop();}};worker.onerror=e=>{$('error').textContent=e.message||'The experiment could not run in this browser.';stop();};worker.postMessage(config);}catch(e){$('error').textContent=e.message;stop();}};
$('cancel').onclick=()=>{stop();$('settings-note').textContent='Experiment stopped. Any displayed results are from the previous completed run.';};
$('scenario').onchange=changed;$('seed').onchange=changed;$('confidence').onchange=changed;
for(const k of ['recall','precision','fpr'])$(k).onchange=()=>{$('policy').value='custom';changed();};
$('policy').onchange=()=>{const strict=$('policy').value==='strict';if($('policy').value!=='custom'){$('recall').value=strict?95:80;$('precision').value=strict?90:60;$('fpr').value=strict?10:50;$('confidence').checked=true;}changed();};
function chart(values,labels,{target=null,second=null,xTitle='',firstLabel='Validation recall',secondLabel='Validation precision'}={}){
 const W=660,H=225,left=45,right=20,top=15,bottom=43,iw=W-left-right,ih=H-top-bottom,x=i=>left+(values.length===1?iw/2:i*iw/(values.length-1)),y=v=>top+(1-v)*ih;
 const series=(a,color)=>`<polyline points="${a.map((v,i)=>`${x(i)},${y(v??0)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>${a.length<=8?a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v??0)}" r="4" fill="${color}"/>`).join(''):''}`;
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${escape(firstLabel)} across ${escape(xTitle)}">${[0,.25,.5,.75,1].map(v=>`<line x1="${left}" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eaf0"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${v*100}%</text>`).join('')}${target===null?'':`<line x1="${left}" x2="${W-right}" y1="${y(target)}" y2="${y(target)}" stroke="#8292a7" stroke-width="1.5" stroke-dasharray="5 4"/>`}${series(values,'#245eea')}${second?series(second,'#d16d20'):''}${labels.map((l,i)=>l===null?'':`<text x="${x(i)}" y="${H-20}" text-anchor="middle">${escape(l)}</text>`).join('')}</svg><div class="legend"><span>${escape(firstLabel)}</span>${second?`<span>${escape(secondLabel)}</span>`:''}${target===null?'':`<span>Recall target ${pct(target)}</span>`}</div>`;
}
function render(){
 const r=result,first=r.runs[0],m=first.summary,p=r.policy,overall=first.decision.status==='fail'||r.stability==='fail'||!r.reproducible?'fail':first.decision.status==='insufficient'||r.stability==='insufficient'?'insufficient':'pass';
 const failed=first.decision.gates.filter(g=>g.status==='fail').map(g=>({recall:'failure-warning recall',precision:'warning precision',fpr:'false-warning rate'}[g.key]));
 let copy=failed.length?`The final test misses the target for ${failed.join(' and ')}.`:first.decision.status==='insufficient'?'The point scores meet your targets, but uncertainty across the held-out machines is still too wide.':'The selected model meets all three requirements on the held-out machines.';
 if(r.scenario==='shift')copy+=' Conditions changed after validation; earlier success did not guarantee later performance.';
 if(r.stability==='fail')copy+=' Retraining also fails the stability checks.';
 $('verdict').className='verdict '+overall;
 $('verdict').innerHTML=`<h2>${overall==='pass'?'The experiment meets the selected requirements':overall==='fail'?'This model does not meet your requirements':'Promising scores. Not enough evidence to pass.'}</h2><p>${copy}</p>`;
 $('run-meta').textContent=`${scenarioNames[r.scenario]} · simulation seed ${r.seed} · ${r.elapsedSeconds.toFixed(1)} seconds in this browser · ${p.confidence?'95% bounds required':'Point-score targets only'}`;
 $('metrics').innerHTML=[['At-risk checks missed',m.fn,`${m.tp} caught out of ${m.atRisk} at-risk checks`,'error'],['False warnings',m.fp,`${num(m.healthy)} healthy checks evaluated`,'error'],['Failures warned about',`${m.warnedEvents} / ${m.events}`,'Events with ≥1 warning in the available pre-failure test window','good']].map(([name,value,caption,cls])=>`<div class="metric ${cls}"><span>${name}</span><strong>${value}</strong><small>${caption}</small></div>`).join('');
 $('baseline').innerHTML=`<tr><td>Never warn</td><td>${pct(r.baseline.accuracy)}</td><td>0 / ${m.atRisk}</td><td>0</td></tr><tr class="selected"><td>Trained classifier</td><td>${pct(m.accuracy)}</td><td>${m.tp} / ${m.atRisk}</td><td>${m.fp}</td></tr>`;
 const selected=r.stages.find(s=>s.machines===r.selectedMachines),passed=r.stages.some(s=>s.validationDecision.status==='pass');
 $('learning-title').textContent=passed?`${r.selectedMachines} training machines cleared validation`:'More training data did not clear the validation policy';
 $('selection-copy').textContent=`${num(r.selectedTrainCount)} training readings were used for the selected model. ${r.selectionReason}. The final test was not used to choose this training size. Selected checkpoint: epoch ${r.selectedEpoch}.`;
 $('learning-chart').innerHTML=chart(r.stages.map(s=>s.validation.recall),r.stages.map(s=>s.machines+' machines'),{target:p.recall,second:r.stages.map(s=>s.validation.precision),xTitle:'training machines'});
 $('stages').innerHTML=r.stages.map(s=>`<tr class="${s.machines===r.selectedMachines?'selected':''}"><td>${s.machines}${s.machines===r.selectedMachines?' · selected':''}</td><td>${num(s.trainCount)}</td><td>${s.trace.length}</td><td>${pct(s.validation.recall)}</td><td>${pill(s.validationDecision.status)}</td></tr>`).join('');
 $('epoch-chart').innerHTML=chart(selected.trace.map(s=>s.recall),selected.trace.map((s,i)=>i===0||i===selected.trace.length-1||i%10===0?'Epoch '+s.epoch:null),{target:p.recall,second:selected.trace.map(s=>s.precision),xTitle:'training epochs'});
 $('epoch-copy').textContent=`${stopNames[selected.stop]}. Ran ${selected.trace.length} epochs; retained epoch ${selected.selectedEpoch}. Stopping on validation is exploratory, not a statistical guarantee from repeated testing.`;
 $('gates').innerHTML=first.decision.gates.map(g=>{const f=g.key==='fpr'?per:pct,name={recall:'At-risk checks caught',precision:'Warnings that were correct',fpr:'False warnings / 1,000 healthy checks'}[g.key];return `<tr><td>${name}</td><td>${f(g.value)}</td><td>${g.interval?g.interval.map(f).join(' – '):'Insufficient support'}</td><td>${g.minimum?'≥':'≤'} ${f(g.target)}</td><td>${pill(g.status)}</td></tr>`;}).join('');
 $('repeat-cards').innerHTML=`<div class="repeat-card"><p class="eyebrow">SAME SEED, SAME SETUP</p><strong>${r.reproducible?'Identical model and predictions':'Exact repeat did not match'}</strong><p>Compared learned weights, preprocessing, warning threshold, and every test prediction in this runtime.</p></div><div class="repeat-card"><p class="eyebrow">DIFFERENT TRAINING SEEDS</p><strong>${statusLabel[r.stability]}</strong><p>Recall spread: ${(r.recallSpread*100).toFixed(1)} percentage points. Prediction agreement: ${pct(r.agreement)}.</p></div>`;
 $('runs').innerHTML=r.runs.map(run=>`<tr><td>${run.id==='seed-11-repeat'?'Seed 11 · exact repeat':`Seed ${run.seed}`}</td><td>${pct(run.summary.recall)}</td><td>${pct(run.summary.precision)}</td><td>${per(run.summary.fpr)}</td><td>${pill(run.decision.status)}</td></tr>`).join('');
 $('repeat-copy').textContent='Stability requires all three distinct-seed runs to meet the policy, with recall spread no larger than 5 percentage points. Three seeds demonstrate variability; they cannot guarantee future retraining outcomes. The exact repeat is excluded from the spread and agreement calculation.';
 renderExamples();
}
function renderExamples(){if(!result)return;const run=result.runs[0],filter=$('filter').value,rows=result.testRows.map((r,i)=>({...r,score:run.probs[i],prediction:run.pred[i]})).filter(r=>filter==='all'||filter==='missed'&&r.y&&!r.prediction||filter==='false'&&!r.y&&r.prediction||filter==='correct'&&r.y&&r.prediction);
 $('examples').innerHTML=rows.slice(0,10).map(r=>`<tr><td>M${String(r.machine+1).padStart(3,'0')} / ${r.hour}h</td><td>${r.x[0].toFixed(2)} mm/s</td><td>${r.x[1].toFixed(1)} °C</td><td>${r.score.toFixed(3)}</td><td>${r.prediction?'Warn':'No warning'}</td><td>${r.y?`Failure in ${r.failureHour-r.hour}h`:'No failure within 24h'}</td></tr>`).join('')||'<tr><td class="empty-row" colspan="6">No checks in this category.</td></tr>';
 $('examples-copy').textContent=`Showing ${Math.min(rows.length,10)} of ${num(rows.length)} matching checks. Warn when model score ≥ ${run.threshold.toFixed(2)}. This score is not a calibrated probability. Future outcomes are shown for evaluation only; the model cannot see them.`;
}
$('filter').onchange=renderExamples;
$('export').onclick=()=>{if(!result)return;const blob=new Blob([JSON.stringify({...result,limitations:['Synthetic simulator only; no real-world reliability claim.','Machine-cluster bootstrap intervals are approximate and per metric.','Validation used for threshold, checkpoint, and training-size selection.','Repeated policy changes after final-test inspection are exploratory.']},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`factory-experiment-${result.scenario}-${result.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
updateDescription();
